from control import *
import cv2
class Saved:
    def __init__(self,name):
        path=OUT+'/'+name
        self.meta=json.load(open(path+'/meta.json')); self.last={'robot_wrist':np.load(path+'/rgb.npy')}; self.depth={'robot_wrist':np.load(path+'/depth_robot_wrist.npy')}
def inspect(name):
    res=Saved(name); rgb=res.last['robot_wrist']; pts=cloud(res)
    masks={'green':(rgb[:,:,1]>rgb[:,:,0]*1.5)&(rgb[:,:,1]>rgb[:,:,2]*1.5)&(rgb[:,:,1]>50),'red':(rgb[:,:,0]>100)&(rgb[:,:,1]<70)&(rgb[:,:,2]<70),'purple':(rgb[:,:,0]>60)&(rgb[:,:,2]>70)&(rgb[:,:,1]<50),'grey':(abs(rgb[:,:,0].astype(float)-rgb[:,:,1])<3)&(abs(rgb[:,:,0].astype(float)-rgb[:,:,2])<3)&(rgb[:,:,0]>65)&(rgb[:,:,0]<160)}
    for key,mask in masks.items():
        n,l,stats,cents=cv2.connectedComponentsWithStats(mask.astype('uint8'))
        for i in range(1,n):
            if stats[i,4]<30: continue
            ps=pts[l==i]
            print(key,'pixels',stats[i,4],'pixcenter',cents[i], 'xyzmed',np.median(ps,axis=0),'min',ps.min(axis=0),'max',ps.max(axis=0))
    np.savez(OUT+'/'+name+'/cloud.npz',points=pts,rgb=rgb)
if __name__=='__main__':
    import sys
    inspect(sys.argv[1])
